// The letter-table (.ltr) resource wrapper, a CRes subclass holding the unigram, bigram and trigram
// letter distributions the random name generator walks.

#ifndef CRESLTR_H
#define CRESLTR_H

#include "exoresman.h"

// The on-disk .ltr header, with signature, version and the number of codes per dimension.
#pragma pack(push, 1)
struct LTRHeader {
    unsigned int  m_dwSignature;
    unsigned int  m_dwVersion;
    unsigned char m_nCodeCount;
};
#pragma pack(pop)

class CResLTR : public CRes {
public:
    CResLTR();
    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 6 slots
    virtual ~CResLTR();  // slots 0-1 (D2+D0)
    virtual int OnResourceFreed();
    virtual int OnResourceServiced();
    // </VTABLE-GEN>

    float*** m_pTrigram[3];
    float**  m_pBigram[3];
    float*   m_pUnigram[3];

    LTRHeader*     m_pHeader;
    unsigned char* m_pTableData;
    unsigned int   m_nTableSize;
    int            m_bLoaded;
};

#endif
